metrics.workdir_dsl:
workspace "Parcel Tracker" "A parcel delivery tracking platform, owned and operated by our company." {

    model {
        customer = person "Customer" "A customer who uses the platform to look up the status of their parcels."

        parcelTracker = softwareSystem "Parcel Tracker" "The parcel delivery tracking platform, owned and operated by our company." {
            webPortal = container "Web Portal" "Where customers look up the status of their shipments." "Web"
            dispatchService = container "Dispatch Service" "Assigns parcels to couriers." "Service"
            pricingLibrary = container "Pricing Rules Library" "Computes delivery prices from weight and zone." "Library" "Library"
            database = container "Database" "Stores shipments and dispatch records." "Database" "Database"

            customer -> webPortal "looks up the status of their parcels"
            webPortal -> pricingLibrary "embeds"
            dispatchService -> pricingLibrary "embeds"
            webPortal -> database "reads shipment records from"
            dispatchService -> database "writes dispatch records to"
        }

        emailProvider = softwareSystem "Email Delivery Provider" "An email delivery provider operated by a different organization." "External"

        dispatchService -> emailProvider "sends customer notification emails to"
    }

    views {
        systemContext parcelTracker "SystemContext" "The system context diagram for the Parcel Tracker." {
            include *
            autoLayout
        }

        container parcelTracker "Containers" "The container diagram for the Parcel Tracker." {
            include *
            autoLayout
        }
    }
}
